using System.Text;
using UnityEngine;

public class FishRuntimeDump
{
    public static void Run()
    {
        StringBuilder sb = new StringBuilder();
        Renderer[] renderers = Object.FindObjectsOfType<Renderer>();

        sb.AppendLine("play=" + Application.isPlaying + " count=" + renderers.Length);

        for (int i = 0; i < renderers.Length; i++)
        {
            Renderer r = renderers[i];
            Bounds b = r.bounds;

            if (b.size.x < 0.4f && b.size.y < 0.4f)
                continue;

            Material m = r.sharedMaterial;
            Transform t = r.transform;

            sb.AppendLine(r.GetType().Name + " " + t.parent != null ? r.GetType().Name + " " + t.parent.name + "/" + t.name : r.GetType().Name + " " + t.name);
            sb.AppendLine("   ctr(" + b.center.x.ToString("0.00") + "," + b.center.y.ToString("0.00") + "," + b.center.z.ToString("0.00") + ") size(" + b.size.x.ToString("0.00") + "," + b.size.y.ToString("0.00") + "," + b.size.z.ToString("0.00") + ")"
                          + " localScale(" + t.localScale.x.ToString("0.00") + "," + t.localScale.y.ToString("0.00") + "," + t.localScale.z.ToString("0.00") + ")"
                          + " enabled=" + r.enabled + " mat=" + (m != null ? m.name + "/" + m.shader.name : "NONE"));
        }

        Camera cam = Camera.main;

        if (cam != null)
            sb.AppendLine("cam y=" + cam.transform.position.y.ToString("0.00") + " ortho=" + cam.orthographicSize.ToString("0.00") + " aspect=" + cam.aspect.ToString("0.000"));

        Debug.Log("[FishRuntimeDump]\n" + sb);
    }
}
